    'terms.body': '''नियम और शर्तें

1. शर्तों की स्वीकृति
खाता बनाकर आप इन नियमों और शर्तों से बंधे होने के लिए सहमत होते हैं।

2. पात्रता
ट्रेडिंग प्लेटफ़ॉर्म का उपयोग करने के लिए आपको अपने क्षेत्राधिकार में वैध आयु का होना चाहिए।

3. जोखिम प्रकटीकरण
ट्रेडिंग में नुकसान का पर्याप्त जोखिम होता है। पिछला प्रदर्शन भविष्य के परिणामों की गारंटी नहीं देता। केवल उतनी पूँजी से ट्रेड करें जितनी आप खोने का जोखिम उठा सकते हैं।

4. खाता सुरक्षा
अपनी लॉगिन जानकारी और अपने खाते के अंतर्गत होने वाली किसी भी गतिविधि की सुरक्षा की ज़िम्मेदारी आपकी है।

5. गोपनीयता
आपका डेटा हमारी गोपनीयता नीति के अनुसार संभाला जाता है।

6. समाप्ति
हम उन खातों को निलंबित या समाप्त करने का अधिकार सुरक्षित रखते हैं जो इन शर्तों या लागू कानूनों का उल्लंघन करते हैं।

(वास्तविक नियम और शर्तें कानूनी टीम द्वारा प्रदान की जाती हैं और यहाँ दिखाई जाती हैं।)''',
